      font-size: 32px;
    }
  }

  &__subtitle {
    margin-top: 0;
    color: var(--color-text-muted);
  }

  &__alert,
  &__error {
    margin-top: 0;
    padding: var(--space-3) var(--space-4);
    border: 1px solid var(--color-error);
    border-radius: var(--radius-sm);
