    color: var(--color-error);
    font-weight: 500;

    p {
      margin: 0 0 var(--space-3);
    }
  }

  &__status {
    margin: 0;
    color: var(--color-text-muted);
  }

  &__tiles {
    margin-top: 0;
    padding: 0;
    border: 0;
  }
}

.choice-tile {
  position: relative;
  display: flex;
  flex: 1 1 0;
  min-width: 130px;
  max-width: 240px;
  min-height: 120px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-4);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  cursor: pointer;

  &:hover {
    border-color: var(--color-action);
  }

  &:has(:focus-visible) {
    box-shadow: var(--focus-ring);
  }

  &--selected,
  &--selected:hover {
    border-color: var(--color-action);
    background: var(--color-surface-highlight);
  }

  &__flag {
    width: 48px;
    height: 32px;
    object-fit: cover;
    border-radius: 4px;
  }

  &__name {
    color: var(--color-text);
    font-size: 20px;
    font-weight: 700;
  }

  &__check {
    position: absolute;
    top: var(--space-3);
    right: var(--space-3);
    color: var(--color-action);
  }

  &--skeleton {
    border-color: var(--color-surface-alt);
    background: var(--color-surface-alt);
    cursor: default;
    animation: tile-pulse 1.4s ease-in-out infinite;

    &:hover {
      border-color: var(--color-surface-alt);
    }
  }
}

@keyframes tile-pulse {
  50% {
    opacity: 0.55;
  }
}

@media (prefers-reduced-motion: reduce) {
  .choice-tile--skeleton {
    animation: none;
  }
}

.button {
  min-height: 48px;
  padding: var(--space-3) var(--space-6);
  border: 1px solid transparent;
  border-radius: var(--radius-pill);
  font: inherit;
  font-weight: 700;
  cursor: pointer;

  &:focus-visible {
    outline: none;
    box-shadow: var(--focus-ring);
  }

  &--cta {
    min-width: 200px;
    background: var(--color-cta);
    color: var(--color-on-cta);

    &:hover:not(:disabled) {
      background: var(--color-cta-hover);
    }
  }

  &--secondary {
    background: var(--color-surface);
    border-color: var(--color-brand);
    color: var(--color-brand);
  }

  &:disabled {
    background: var(--color-disabled-bg);
    color: var(--color-disabled-text);
    cursor: not-allowed;
  }
}
.wizard-header {
  background: var(--color-brand);
  color: var(--color-surface);

  &__wordmark {
    font-size: 24px;
    font-weight: 700;
  }

  &__plus {
    color: var(--color-cta);
  }

  &__country {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 600;
  }

  &__flag {
    width: 32px;
    height: 24px;
    object-fit: cover;
    border-radius: 4px;
  }

  /* Visually hidden on narrow screens, still read by assistive tech. */
  &__country--with-icon &__country-name {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  &__change {
    min-height: 48px;
    padding: var(--space-2) var(--space-4);
    border: 1px solid var(--color-surface);
    border-radius: var(--radius-pill);
    background: transparent;
    color: var(--color-surface);
    font: inherit;
    font-weight: 700;
    white-space: nowrap;
    cursor: pointer;

    &:hover {
      background: var(--color-on-brand-overlay);
    }

    &:focus-visible {
      outline: 2px solid var(--color-surface);
      box-shadow: var(--focus-ring);
    }
  }
}

@media (min-width: 576px) {
  .wizard-header__country--with-icon .wizard-header__country-name {
    position: static;
    width: auto;
    height: auto;
    margin: 0;
    overflow: visible;
    clip-path: none;
  }
